"""Canonical compressed bundle: tar.gz archive from JSON request, output as JSON result."""

import base64
import gzip
import io
import json
import hashlib
import os
import sys
import tarfile

def process_request(data):
    """Process the JSON request and produce output."""
    # data should be a dict with 'members' list

    members = data.get('members')
    if not isinstance(members, list):
        return {"error": "invalid_request"}

    # Validate each member
    for member in members:
        if not isinstance(member, dict):
            return {"error": "invalid_request"}
        if not all(k in member for k in ('path', 'content_b64', 'mode')):
            return {"error": "invalid_request"}
        # Validate path
        path = member.get('path')
        if not isinstance(path, str):
            return {"error": "invalid_decode"}
        # Check path components
        if '/' in path:
            for comp in path.split('/'):
                if comp == '.' or comp == '..' or comp == '':
                    return {"error": "invalid_request"}
        # Check no backslash
        if '\\' in path:
            return {"error": "invalid_request"}
        # Check no control characters (bytes in path should be valid utf-8)
        # Check length constraint
        if path.encode('utf-8') > 100:
            return {"error": "invalid_request"}
        # Validate mode
        mode = member.get('mode')
        if not isinstance(mode, int) or mode < 0 or mode > 511:
            return {"error": "invalid_request"}

    # Sort by path (Unicode code-point order)
    sorted_members = sorted(members, key=lambda m: m['path'])

    # Create tar.gz in memory
    buf = io.BytesIO()

    # First create the gzip
    gz = gzip.GZWrapper(buf)
    tar = tarfile.open(fileobj=gz, mode='w')

    # Write each member
    for member in sorted_members:
        content = base64.b64decode(member['content_b64'])
        path = member['path']
        mode_val = member['mode']

        # Create tarinfo
        tarinfo = tarfile.TarInfo(name=path, mode=mode_val, type=tarfile.REG, size=len(content))
        tarinfo.mtime = 0  # mtime = 0
        tarinfo.uid = 0
        tarinfo.gid = 0
        tarinfo.uname = ''
        tarinfo.gname = ''
        tarfile.TarInfo()  # This is tarinfo

        tar.addfile(tarinfo)
        tar.write(content)

    tar.close()

    # Get the compressed bytes
    gz.close()
    compressed_data = buf.getvalue()

    # Compute sha256
    sha256_hash = hashlib.sha256(compressed_data).hexdigest()

    # Base64 encode the compressed bytes
    bundle_b64 = base64.b64encode(compressed_data).decode('ascii')

    return {
        'format': 'tar+gzip',
        'bundle_b64': bundle_b64,
        'sha256': sha256_hash
    }


def main():
    """Main entry point."""
    import sys

    # Read stdin
    stdin_text = sys.stdin.read()

    try:
        data = json.loads(stdin_text)
    except (json.JSONDecodeError, ValueError):
        return

    result = process_request(data)

    # Output result as JSON
    print(json.dumps(result))


